script:
country_event = {
	id = precursor.301
	title = "precursor.301.name"
	desc = {
		trigger = {
			NOR = {
				is_machine_empire = yes
				is_hive_empire = yes
			}
		}
		text = precursor.301.a.desc
	}
	desc = {
		trigger = {
			NOR = {
				is_machine_empire = yes
				is_hive_empire = yes
			}
		}
		text = precursor.301.b.desc
	}
	desc = {
		trigger = {
			NOR = {
				is_machine_empire = yes
				is_hive_empire = yes
			}
		}
		text = precursor.301.c.desc
	}
	desc = {
		trigger = {
			NOR = {
				is_machine_empire = yes
				is_hive_empire = yes
			}
		}
		text = precursor.301.d.desc
	}
	desc = {
		trigger = {
			is_machine_empire = yes
		}
		text = precursor.301.e.desc
	}
	desc = {
		trigger = {
			is_hive_empire = yes
		}
		text = precursor.301.f.desc
	}
	picture = GFX_evt_archaeological_dig
	location = event_target:precursor_planet
	trackable = yes
	is_triggered_only = yes

	trigger = {
		is_ai = no
		years_passed > 50
		NOT = { has_country_flag = ongoing_precursor_artifact }
		OR = {
			AND = {
				has_event_chain = "vultaum_chain"
				NOT = {
					has_completed_event_chain_counter = {
						event_chain = vultaum_chain
						counter = vultaum_artifacts
					}
				}
				has_accessible_precursor_system = { PRECURSOR_FLAG = precursor_1 }
			}
			AND = {
				has_event_chain = "yuht_chain"
				NOT = {
					has_completed_event_chain_counter = {
						event_chain = yuht_chain
						counter = yuht_artifacts
					}
				}
				has_accessible_precursor_system = { PRECURSOR_FLAG = precursor_2 }
			}
			AND = {
				has_event_chain = "first_league_chain"
				NOT = {
					has_completed_event_chain_counter = {
						event_chain = first_league_chain
						counter = first_league_artifacts
					}
				}
				has_accessible_precursor_system = { PRECURSOR_FLAG = precursor_3 }
			}
			AND = {
				has_event_chain = "irassian_chain"
				NOT = {
					has_completed_event_chain_counter = {
						event_chain = irassian_chain
						counter = irassian_artifacts
					}
				}
				has_accessible_precursor_system = { PRECURSOR_FLAG = precursor_4 }
			}
			AND = {
				has_event_chain = "cybrex_chain"
				NOT = {
					has_completed_event_chain_counter = {
						event_chain = cybrex_chain
						counter = cybrex_artifacts
					}
				}
				has_accessible_precursor_system = { PRECURSOR_FLAG = precursor_5 }
			}
		}
	}

	weight_multiplier = {
		factor = 1
		# NOTE: although gestalts are ineligible for the other events in this series, that actually increases their odds of receiving this one (as opposed to nothing at all). This is because 'on_actions' do not count weightings for random_events whose triggers will fail. The same therefore applies to regular empires who have already triggered the one-off events in this series.
		modifier = {
			factor = 0.9
			is_gestalt = yes
		}
		modifier = {
			factor = 1.25
			years_passed > 100
		}
		modifier = {
			factor = 0.75
			has_country_flag = recent_new_precursor
		}
		modifier = {
			factor = 1.5
			has_origin = origin_shoulders_of_giants
			has_country_flag = origin_shoulders_closure
		}
	}

	immediate = {
		# Reduce odds of firing in (relatively) quick succession
		set_timed_country_flag = {
			flag = recent_new_precursor
			years = 9
		}
		# Spawn a Special Project
		switch = {
			trigger = has_event_chain
			vultaum_chain = {
				if = {
					limit = { has_accessible_precursor_system = { PRECURSOR_FLAG = precursor_1 } }
					spawn_precursor_anomaly_effect = {
						PRECURSOR_FLAG = precursor_1
						PROJECT_NAME = VULTAUM_ARTIFACT_FOUND
					}
				}
			}
			yuht_chain = {
				if = {
					limit = { has_accessible_precursor_system = { PRECURSOR_FLAG = precursor_2 } }
					spawn_precursor_anomaly_effect = {
						PRECURSOR_FLAG = precursor_2
						PROJECT_NAME = YUHT_ARTIFACT_FOUND
					}
				}
			}
			first_league_chain = {
				if = {
					limit = { has_accessible_precursor_system = { PRECURSOR_FLAG = precursor_3 } }
					spawn_precursor_anomaly_effect = {
						PRECURSOR_FLAG = precursor_3
						PROJECT_NAME = LEAGUE_ARTIFACT_FOUND
					}
				}
			}
			irassian_chain = {
				if = {
					limit = { has_accessible_precursor_system = { PRECURSOR_FLAG = precursor_4 } }
					spawn_precursor_anomaly_effect = {
						PRECURSOR_FLAG = precursor_4
						PROJECT_NAME = IRASSIAN_ARTIFACT_FOUND
					}
				}
			}
			cybrex_chain = {
				if = {
					limit = { has_accessible_precursor_system = { PRECURSOR_FLAG = precursor_5 } }
					spawn_precursor_anomaly_effect = {
						PRECURSOR_FLAG = precursor_5
						PROJECT_NAME = CYBREX_ARTIFACT_FOUND
					}
				}
			}
		}
	}

	option = {
		name = precursor.301.a
		custom_tooltip = new_precursor_project
	}
}

